package com.oms.inventory.service.impl;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import javax.annotation.Resource;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import static com.oms.inventory.service.impl.WarehouseAllocationPlanner.*;

/** Atomic source consumption and physical outbound; the receipt commits with all stock changes. */
@Service
public class OrderVirtualOutboundService {
    @Resource private JdbcTemplate jdbc;
    private static final ObjectMapper JSON=new ObjectMapper();
    private Object canonical(Object value){if(value instanceof Map){Map<String,Object> copy=new TreeMap<>();((Map<?,?>)value).forEach((k,v)->copy.put(k.toString(),canonical(v)));return copy;}if(value instanceof List){List<Object> copy=new ArrayList<>();for(Object item:(List<?>)value)copy.add(canonical(item));return copy;}return value;}
    private String encode(Object value){try{return JSON.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("虚拟出库指令无法编码");}}
    private String hash(Map<String,Object> command){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(encode(canonical(command)).getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:digest)out.append(String.format("%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalArgumentException("虚拟出库指令无法校验");}}
    @SuppressWarnings("unchecked") private Map<String,Object> previous(String company,String request,String hash){List<Map<String,Object>> rows=jdbc.queryForList("SELECT payload_hash,receipt_json FROM oms_order_virtual_outbound WHERE company_code=? AND request_id=?",company,request);if(rows.isEmpty())return null;require(hash.equals(s(rows.get(0),"payload_hash")),"相同出库请求的内容发生变化，禁止重复记账");try{return JSON.readValue(s(rows.get(0),"receipt_json"),Map.class);}catch(Exception e){throw new IllegalArgumentException("原虚拟出库回执损坏，请核对台账");}}
    @SuppressWarnings("unchecked") public Map<String,Object> receipt(String company,String request){require(company!=null&&company.matches("[A-Za-z0-9_-]{1,50}")&&request.matches("[A-Za-z0-9_-]{16,64}"),"虚拟出库标识无效");List<Map<String,Object>> rows=jdbc.queryForList("SELECT receipt_json FROM oms_order_virtual_outbound WHERE company_code=? AND request_id=?",company.toUpperCase(Locale.ROOT),request);if(rows.isEmpty()){Map<String,Object> result=new LinkedHashMap<>();result.put("state","MISSING");return result;}try{return JSON.readValue(s(rows.get(0),"receipt_json"),Map.class);}catch(Exception e){throw new IllegalArgumentException("原出库回执损坏");}}
    @Transactional(rollbackFor=Exception.class,timeout=30,isolation=Isolation.READ_COMMITTED)
    @SuppressWarnings("unchecked") public Map<String,Object> outbound(String company,Map<String,Object> command){
        require(company!=null&&company.matches("[A-Za-z0-9_-]{1,50}"),"公司编码无效");company=company.toUpperCase(Locale.ROOT);
        String request=s(command,"request_id"),sn=s(command,"shipment_sn"),tid=s(command,"platform_tid"),actor=s(command,"operator_name");long channel=n(command,"channel_id");
        require(request.matches("[A-Za-z0-9_-]{16,64}")&&sn.matches("[A-Za-z0-9_-]{1,64}")&&channel>0&&tid.matches("[0-9]{1,64}"),"虚拟出库标识无效");require(!actor.isEmpty()&&actor.length()<=100,"出库操作人无效");
        Object raw=command.get("lines");require(raw instanceof List&&!((List<?>)raw).isEmpty()&&((List<?>)raw).size()<=500,"出库明细须为1至500行");
        List<Map<String,Object>> lines=new ArrayList<>();Set<Long> seen=new HashSet<>();TreeSet<String> skus=new TreeSet<>();long total=0;
        for(Object item:(List<?>)raw){require(item instanceof Map,"出库明细无效");Map<String,Object> line=(Map<String,Object>)item;long quantity=n(line,"quantity");require(n(line,"allocation_id")>0&&seen.add(n(line,"allocation_id"))&&quantity>0&&quantity<=100000000&&n(line,"outbound_before")>=0&&!s(line,"sku_sn").isEmpty(),"出库明细重复、数量或版本无效");total=Math.addExact(total,quantity);skus.add(s(line,"sku_sn"));lines.add(line);}
        require(total==n(command,"quantity"),"出库明细与汇总数量不一致");String digest=hash(command);Map<String,Object> old=previous(company,request,digest);if(old!=null)return old;
        // Every stock writer uses the company/SKU mutex; recheck idempotency after acquiring it.
        for(String sku:skus)require(jdbc.queryForList("SELECT id FROM oms_inventory WHERE company_code=? AND sku_sn=? FOR UPDATE",company,sku).size()==1,"商品汇总库存缺失");old=previous(company,request,digest);if(old!=null)return old;
        lines.sort(Comparator.comparingLong(l->n(l,"allocation_id")));List<Map<String,Object>> receipts=new ArrayList<>();Map<String,Long> publicConsumed=new TreeMap<>();Map<Long,Map<String,Object>> journalBefore=new TreeMap<>();Map<Long,Long> journalQuantity=new TreeMap<>();
        for(Map<String,Object> line:lines){
            List<Map<String,Object>> found=jdbc.queryForList("SELECT * FROM oms_order_warehouse_allocation WHERE company_code=? AND id=? AND channel_id=? AND platform_tid=? FOR UPDATE",company,line.get("allocation_id"),channel,tid);require(found.size()==1,"出库占用来源不存在或不属于本订单");Map<String,Object> allocation=found.get(0);long quantity=n(line,"quantity");
            require("OCCUPIED".equals(s(allocation,"status")),"原仓库占用已释放");for(String field:Arrays.asList("sku_sn","store_code","source_type","owner_code","real_store_code"))require(s(line,field).equals(s(allocation,field)),"出库来源身份不一致");for(String field:Arrays.asList("batch_id","stock_source_id"))require(n(line,field)==n(allocation,field),"出库批次或预占来源不一致");
            require(n(line,"outbound_before")==n(allocation,"outbound_quantity")&&quantity<=n(allocation,"quantity")-n(allocation,"outbound_quantity"),"出库量已变化或超过剩余占用");require(s(allocation,"outbound_shipment_sn").isEmpty()||sn.equals(s(allocation,"outbound_shipment_sn")),"该占用来源已关联其他发货单");
            Map<String,Object> demand=jdbc.queryForMap("SELECT * FROM oms_order_stock_demand WHERE company_code=? AND id=? FOR UPDATE",company,allocation.get("demand_id"));require(!"CANCELLED".equals(s(demand,"status"))&&s(line,"platform_oid").equals(s(demand,"platform_oid"))&&s(line,"sku_sn").equals(s(demand,"sku_sn")),"销售需求已取消或身份不一致");
            Map<String,Object> source=jdbc.queryForMap("SELECT * FROM oms_order_stock_source WHERE company_code=? AND id=? AND demand_id=? FOR UPDATE",company,allocation.get("stock_source_id"),allocation.get("demand_id"));require(n(source,"reserved")==1&&s(source,"source_type").equals(s(allocation,"source_type"))&&s(source,"sku_sn").equals(s(line,"sku_sn")),"逻辑预占来源已失效");
            require(n(source,"outbound_quantity")<=n(source,"quantity")&&n(demand,"outbound_quantity")<=n(demand,"reserved_quantity"),"出库来源累计数量异常");
            String sku=s(line,"sku_sn"),store=s(line,"store_code");Map<String,Object> warehouse=jdbc.queryForMap("SELECT * FROM wms_inventory WHERE company_code=? AND sku_sn=? AND store_code=? FOR UPDATE",company,sku,store);
            Map<String,Object> batch=jdbc.queryForMap("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=? AND sku_sn=? AND store_code=? FOR UPDATE",company,line.get("batch_id"),sku,store);
            for(String prefix:Arrays.asList("zp","cp")){Map<String,Object> sums=jdbc.queryForMap("SELECT SUM("+prefix+"_actual_number) actual,SUM("+prefix+"_available_number) available,SUM("+prefix+"_lock_number) locked FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=?",company,sku,store);require(n(warehouse,prefix+"_actual_number")==n(warehouse,prefix+"_available_number")+n(warehouse,prefix+"_lock_number")&&n(warehouse,prefix+"_actual_number")==n(sums,"actual")&&n(warehouse,prefix+"_available_number")==n(sums,"available")&&n(warehouse,prefix+"_lock_number")==n(sums,"locked"),"仓库汇总与批次库存不一致");require(n(batch,prefix+"_actual_number")==n(batch,prefix+"_available_number")+n(batch,prefix+"_lock_number")&&n(batch,prefix+"_available_number")>=0&&n(batch,prefix+"_lock_number")>=0,"批次库存余额异常");}
            long owed=jdbc.queryForObject("SELECT COALESCE(SUM(original_quantity-consumed_quantity-released_quantity),0) FROM rule_stock_reservation WHERE company_code=? AND sku_sn=? AND batch_id=?",Long.class,company,sku,line.get("batch_id"));long publicOwed=jdbc.queryForObject("SELECT COALESCE(SUM(quantity-outbound_quantity),0) FROM oms_order_warehouse_allocation WHERE company_code=? AND batch_id=? AND source_type='PUBLIC_EXTRA' AND status='OCCUPIED'",Long.class,company,line.get("batch_id"));require(n(batch,"zp_lock_number")>=owed+publicOwed&&n(batch,"zp_lock_number")>=quantity,"批次占用不足以覆盖来源余额");
            if("LOCK".equals(s(source,"source_type"))){
                require(store.equals(s(source,"store_code")),"原渠道锁库仓与出库仓不一致");Map<String,Object> lock=jdbc.queryForMap("SELECT r.*,x.id result_id FROM rule_stock_reservation r JOIN rule_stock_result x ON x.company_code=r.company_code AND x.rule_id=r.rule_id AND x.sku_sn=r.sku_sn WHERE r.company_code=? AND r.id=? AND r.sku_sn=? AND r.channel_id=? AND r.batch_id=? FOR UPDATE",company,source.get("source_id"),sku,channel,line.get("batch_id"));
                require(jdbc.update("UPDATE rule_stock_reservation SET occupied_quantity=occupied_quantity-?,consumed_quantity=consumed_quantity+? WHERE id=? AND occupied_quantity>=?",quantity,quantity,lock.get("id"),quantity)==1,"原渠道锁库占用不足");require(jdbc.update("UPDATE rule_stock_result SET occupied_quantity=occupied_quantity-?,consumed_quantity=consumed_quantity+? WHERE id=? AND occupied_quantity>=?",quantity,quantity,lock.get("result_id"),quantity)==1,"渠道锁库单占用不足");
                jdbc.update("UPDATE rule_stock_result SET release_status='RELEASED' WHERE id=? AND release_status='PARTIAL' AND occupied_quantity=0 AND allocated_quantity=consumed_quantity+released_quantity",lock.get("result_id"));
                jdbc.update("UPDATE rule_stock_info h SET status=10,revision=revision+1 WHERE h.company_code=? AND h.id=? AND h.status=11 AND NOT EXISTS(SELECT 1 FROM rule_stock_result r WHERE r.company_code=h.company_code AND r.rule_id=h.id AND r.status='SUCCESS' AND r.release_status<>'RELEASED')",company,lock.get("rule_id"));
            }else{require("PUBLIC_EXTRA".equals(s(source,"source_type"))&&n(source,"source_id")==0,"不支持该预占来源类型");publicConsumed.merge(sku,quantity,Long::sum);}
            require(jdbc.update("UPDATE oms_order_stock_source SET outbound_quantity=outbound_quantity+? WHERE company_code=? AND id=? AND quantity-outbound_quantity>=?",quantity,company,source.get("id"),quantity)==1,"逻辑预占来源余额不足");require(jdbc.update("UPDATE oms_order_stock_demand SET outbound_quantity=outbound_quantity+? WHERE company_code=? AND id=? AND reserved_quantity-outbound_quantity>=?",quantity,company,demand.get("id"),quantity)==1,"销售需求剩余预占不足");
            require(jdbc.update("UPDATE wms_inventory_batch SET zp_actual_number=zp_actual_number-?,zp_lock_number=zp_lock_number-?,version=version+1 WHERE company_code=? AND id=? AND zp_lock_number>=? AND zp_actual_number>=?",quantity,quantity,company,batch.get("id"),quantity,quantity)==1,"批次占用库存不足");require(jdbc.update("UPDATE wms_inventory SET zp_actual_number=zp_actual_number-?,zp_lock_number=zp_lock_number-?,version=version+1 WHERE company_code=? AND id=? AND zp_lock_number>=? AND zp_actual_number>=?",quantity,quantity,company,warehouse.get("id"),quantity,quantity)==1,"仓库占用库存不足");
            require(jdbc.update("UPDATE oms_inventory SET total_stock=total_stock-?,reserved_stock=reserved_stock-?,version=version+1 WHERE company_code=? AND sku_sn=? AND total_stock>=? AND reserved_stock>=?",quantity,quantity,company,sku,quantity,quantity)==1,"公司库存或预占余额不足");require(jdbc.update("UPDATE oms_channel_inventory SET reserved_stock=reserved_stock-?,version=version+1 WHERE company_code=? AND sku_sn=? AND channel_id=? AND reserved_stock>=?",quantity,company,sku,channel,quantity)==1,"渠道预占余额不足");
            jdbc.update("UPDATE oms_order_warehouse_allocation SET outbound_quantity=outbound_quantity+?,outbound_shipment_sn=? WHERE company_code=? AND id=?",quantity,sn,company,allocation.get("id"));journalBefore.putIfAbsent(n(batch,"id"),batch);journalQuantity.merge(n(batch,"id"),quantity,Long::sum);
            jdbc.update("INSERT INTO oms_order_stock_event(company_code,demand_id,action,quantity,message) VALUES (?,?,'VIRTUAL_OUTBOUND',?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity),message=VALUES(message)",company,demand.get("id"),quantity,"发货单 "+sn+" 虚拟出库，核销逻辑预占及仓库占用");
            Map<String,Object> receipt=new LinkedHashMap<>(line);receipt.put("outbound_quantity",n(line,"outbound_before")+quantity);receipts.add(receipt);
        }
        for(Long batchId:journalBefore.keySet())journal(journalBefore.get(batchId),journalQuantity.get(batchId),request,sn,actor);
        // Ordinary quota was already occupied at sale; consumption must not return it to availability.
        for(Map.Entry<String,Long> entry:publicConsumed.entrySet())jdbc.update("UPDATE oms_channel_inventory SET quota_stock=GREATEST(0,quota_stock-?) WHERE company_code=? AND channel_id=? AND sku_sn=?",entry.getValue(),company,channel,entry.getKey());
        for(String sku:skus)OrderStockService.refresh(jdbc,company,sku,channel);
        Map<String,Object> result=new LinkedHashMap<>();result.put("request_id",request);result.put("shipment_sn",sn);result.put("quantity",total);result.put("state","COMPLETED");result.put("lines",receipts);
        jdbc.update("INSERT INTO oms_order_virtual_outbound(company_code,request_id,shipment_sn,channel_id,platform_tid,payload_hash,receipt_json,quantity,operator_name) VALUES (?,?,?,?,?,?,?,?,?)",company,request,sn,channel,tid,digest,encode(result),total,actor);return result;
    }
    private void journal(Map<String,Object> before,long quantity,String request,String sn,String actor){Map<String,Object> after=jdbc.queryForMap("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=?",before.get("company_code"),before.get("id"));List<Object> args=new ArrayList<>(Arrays.asList(before.get("company_code"),before.get("store_code"),before.get("sku_sn"),before.get("id"),before.get("batch_code"),"ZP","VIRTUAL_OUTBOUND",request,sn,-quantity,"订单虚拟出库",0,actor.substring(0,Math.min(64,actor.length()))));StringBuilder columns=new StringBuilder("company_code,store_code,sku_sn,batch_id,batch_code,inventory_type,operation_type,request_id,relation_sn,change_quantity,change_reason,operator_id,operator_name");for(String key:Arrays.asList("zp_actual_number","cp_actual_number","zp_available_number","cp_available_number","zp_lock_number","cp_lock_number")){columns.append(",old_").append(key).append(",new_").append(key);args.add(before.get(key));args.add(after.get(key));}jdbc.update("INSERT INTO wms_inventory_change_history("+columns+") VALUES ("+String.join(",",Collections.nCopies(args.size(),"?"))+")",args.toArray());}
}
